using namespace visionflow;
namespace {int checks=0;void check(bool b,const char* s){++checks;if(!b)throw std::runtime_error(s);}template<class F>void reject(F f){++checks;try{f();}catch(...){return;}throw std::runtime_error("Expected rejection");}
QImage stripe(){QImage im(640,200,QImage::Format_Grayscale8);im.fill(20);for(int y=0;y<200;++y)for(int x=120;x<520;++x)im.scanLine(y)[x]=220;return im;}
class Adapter:public AcquisitionAdapter {public:AcquisitionCapabilities capabilities()const override{return {"webcam",true};}ImageFrame acquire(const AcquisitionRequest&)const override{auto im=stripe();return ImageFrame::fromBuffer(im.constBits(),im.sizeInBytes(),640,200,im.bytesPerLine(),PixelFormat::Gray8);}};
CalibrationModelRecord teach(MeasurementWorkspace& w,const MeasurementCamera& c,const MeasurementSetupDescriptor& s,double mm){IndependentCaptureRequest req;req.origin=SourceOrigin::CameraAcquired;req.camera=c;req.setup=s;IndependentCaptureBackend backend{[&]{return QVector<DeviceBinding>{c.device};},[](const DeviceBinding&,const GeometryDescriptor&){return std::make_unique<Adapter>();}};IndependentCalibrationSession session;check(session.accept(IndependentCalibrationSession::run(session.begin(req),backend)),"Actual fixture probe");auto& math=session.math();check(math.accept(CalibrationWizardSession::run(math.scanPair("width",{{"image"},ScanSegment{{20,100},{620,100},4}}))),"Real caliper");math.setKnownMillimetres(mm);auto r=math.calculate().named("Scale");const SetupReference ref{c.id,s.id,s.revision};w.calibrations().save(ref,r);w.calibrations().setOperational(c.id,s.id);w.calibrations().activate(ref,r.contentId(),session);return r;}
const ToolResult& result(const CycleResult& c,const QString& id){for(const auto& r:c.tools)if(r.toolId==id)return r;throw std::runtime_error("Missing result");}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QTemporaryDir dir(QDir::currentPath()+"/scoped-editor-XXXXXX");check(dir.isValid(),"Build fixture");const auto path=dir.filePath("project.vfproject"),imagePath=dir.filePath("stripe.png");check(stripe().save(imagePath),"PNG");ProjectService project;project.createProject("Project","",path,"file");project.save();MeasurementWorkspace w(path,project.project().id,[]{return true;});MeasurementSetupContract contract;
for(int i=0;i<2;++i){const auto id=QString::number(i);contract.cameras.append({{"c"+id},"Camera "+id,{"webcam","717"+id,DeviceIdentityConfidence::ProviderReported,1,{true,true,false,false}}});contract.setups.append({{"s"+id},contract.cameras.last().id,"Setup "+id,"lens","plane",1,1,{{640,200},{},{},true}});}w.replace(contract);teach(w,contract.cameras[0],contract.setups[0],10);teach(w,contract.cameras[1],contract.setups[1],20);
for(const auto type:{ApplicationType::Measurement,ApplicationType::DefectInspection,ApplicationType::RobotGuidance}){
project.createRecipe("Recipe "+typeKey(type),"",type,"file");const auto source=project.setImageFile(imagePath),left=project.addTool("edge_point"),right=project.addTool("edge_point"),measurement=project.addTool("measurement"),raw=project.addTool("calculate");for(auto t:project.tools()){if(t.id==left || t.id==right){t.parameters["scanRoi"]=ToolRoi{{source+"/image"},ScanSegment{{20,100},{620,100},4}}.toJson();t.parameters["polarity"]=t.id==left ? "rising":"falling";}project.updateTool(t);}project.setConnections({{source,"image",left,"image"},{source,"image",right,"image"},{left,"point",measurement,"p1"},{right,"point",measurement,"p2"},{left,"point",raw,"p1"},{right,"point",raw,"p2"}});
const SetupReference a{contract.cameras[0].id,contract.setups[0].id,1},b{contract.cameras[1].id,contract.setups[1].id,1};project.bindSourceSetup(source,a.toJson());project.save();const auto bytes=ProjectRepository::encode(project.project());project.bindSourceSetup(source,a.toJson());check(!project.dirty() && ProjectRepository::encode(project.project())==bytes,"Binding no-op preserves bytes/version");ProjectService reopened;reopened.openProject(path);reopened.selectRecipe(project.activeRecipe()->id);check(SystemCalibration::setupReference(*reopened.activeRecipe())==std::optional(a),"Binding persists");
auto recipe=*project.activeRecipe();const auto snapshot=*w.forRecipe(recipe);auto run=[&](const Recipe& r,const ActiveCalibrationSnapshot& s){return ExecutionService{}.run(r.definition,dir.path(),r.id,"config",{},{},{},[&](const ImageFrame& f){return SystemCalibration::resolve(s,r,dir.path(),f);},nullptr,w.acquisition(r));};auto cycle=run(recipe,snapshot);check(cycle.state==ExecutionState::Done,"Scoped Editor real file");check(std::abs(std::get<double>(result(cycle,measurement).outputs["value"].data)-10)<.001,"A oracle");
auto worldRecipe=recipe;auto worldTools=editorTools(recipe.definition);ToolDefinition circle;circle.id=QUuid::createUuid().toString(QUuid::WithoutBraces);circle.kind="circle_fit";circle.name="World circle";circle.enabled=true;circle.parameters=defaultParameters(circle.kind);circle.parameters["mode"]="calibrated";circle.parameters["scanRoi"]=ToolRoi{snapshot.record.setup().target,Annulus{{8,2.5},.5,1}}.toJson();circle.parameters["worldCalibration"]=SystemCalibration::binding(snapshot,source,source+"/image").toJson();worldTools.append(circle);worldRecipe.definition=withEditorTools(worldRecipe.definition,worldTools);SystemCalibration::prepareRecipe(snapshot,worldRecipe,dir.path());check(SystemCalibration::impact(snapshot,worldRecipe,dir.path()).join(" ").contains("yeniden"),"Exact world ROI impact is explicit");
EditorSession editor;EditorContext context{project.project().id,path,recipe.id,recipe.definition,{},{{"contentId",snapshot.selection.contentId},{"revision",snapshot.selection.revision}}};check(editor.acceptCycle(cycle,editor.signature(context),context),"Editor cache");const auto captured=editor.signature(context);w.calibrations().disconnect(b.camera);check(w.forRecipe(recipe)->selection==snapshot.selection && editor.signature(context)==captured,"Unused camera disconnect preserves A");
auto changed=contract;changed.cameras[0].name="Renamed";changed.setups[0].name="Renamed setup";w.environment();w.replace(changed);check(w.forRecipe(recipe)->scope==snapshot.scope,"Rename preserves physical cache scope");
const auto replacement=teach(w,contract.cameras[0],contract.setups[0],30);const auto newSnapshot=*w.forRecipe(recipe);reject([&]{SystemCalibration::prepareRecipe(newSnapshot,worldRecipe,dir.path());});auto newContext=context;newContext.systemCalibration={{"contentId",newSnapshot.selection.contentId},{"revision",newSnapshot.selection.revision}};editor.calibrationChanged(newContext);const auto evaluation=editor.evaluation(newContext);check(evaluation.cache.contains(source) && evaluation.cache.contains(left) && evaluation.cache.contains(raw) && !evaluation.cache.contains(measurement),"Calibration invalidates mm and preserves raw cache");auto target=ExecutionService{}.runTool(recipe.definition,dir.path(),recipe.id,"config",{},measurement,evaluation,[&](const ImageFrame& f){return SystemCalibration::resolve(newSnapshot,recipe,dir.path(),f);});check(target.acquisitions==0 && result(target,measurement).state==ExecutionState::Done,"TargetOnly acquisition0");check(std::abs(std::get<double>(result(target,measurement).outputs["value"].data)-30)<.001,"Changed A oracle");
reject([&]{auto wrong=newSnapshot;wrong.scope["target"]=b.toJson();SystemCalibration::decodeEvidence(SystemCalibration::evidence(wrong,source,source+"/image"));});
project.bindSourceSetup(source,b.toJson());reject([&]{w.forRecipe(*project.activeRecipe());});teach(w,contract.cameras[1],contract.setups[1],20);auto other=run(*project.activeRecipe(),*w.forRecipe(*project.activeRecipe()));check(std::abs(std::get<double>(result(other,measurement).outputs["value"].data)-20)<.001,"B oracle/source switch");teach(w,contract.cameras[0],contract.setups[0],10);
project.bindSourceSetup(source,a.toJson());auto cameraRecipe=*project.activeRecipe();auto cameraTools=editorTools(cameraRecipe.definition);for(auto& t:cameraTools)if(t.id==source){t.kind="webcam";t.parameters=defaultParameters("webcam");}cameraRecipe.definition=withEditorTools(cameraRecipe.definition,cameraTools);CycleResult failed;ToolResult sourceFailure;sourceFailure.toolId=source;sourceFailure.state=ExecutionState::Error;failed.tools.append(sourceFailure);w.observeAcquisition(*project.activeRecipe(),failed);check(w.forRecipe(*project.activeRecipe()).has_value(),"Offline file error does not revoke physical camera");w.observeAcquisition(cameraRecipe,failed);reject([&]{w.forRecipe(cameraRecipe);});teach(w,contract.cameras[0],contract.setups[0],10);
}
QTextStream(stdout)<<checks<<" scoped Editor checks passed\n";return 0;}catch(const std::exception& e){QTextStream(stderr)<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
